void CSndInstance::SetPan(int pan)
{
	/* 0x2efd40 */
	if (CSnd::m_isDisabled)
		return;

	while (m_handle == SND_HANDLE_PENDING)
		snd_FlushSoundCommands();

	snd_SetSoundVolPan(m_handle, 0x7fffffff, pan);
}

